INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/anansi', 'classeur_modes', 'race', 26, 'Anansi', NULL, NULL, 'races/anansi', NULL, NULL, 'Les attaques vont obtenir un effet secondaire selon la magie innée : Arcane = Vampirise 1d6 barrière à la cible | Nécromancie= Inflige Poison 1 automatiquement | Ombre = Réduit de 5 l''initiative de la cible touchée pour le prochain tour', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A139:Y141', NULL);
INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/drakos', 'classeur_modes', 'race', 11, 'Drakos', NULL, NULL, 'races/drakos', NULL, NULL, '(Action) Permet une attaque de souffle de l''élément de la magie innée, inflige 3d6/NPM dégâts et possède une portée de 4. Elle ne bénéficie pas des boosts de dégâts donnés par le mode hyper ou autre (mais est influencée par les postures). Demande un jet qui est choisi entre toutes les compétences d''attaques disponibles.', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A94:Y96', NULL);
INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/drassahthac', 'classeur_modes', 'race', 14, 'Drassah''thac', NULL, NULL, 'races/drassahthac', NULL, NULL, 'Permet de relancer un jet de dés (alliés, ennemis, soi-même), peu importe la nature (2 fois/Mode Hyper).', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A103:Y105', NULL);
INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/elfe-argente', 'classeur_modes', 'race', 4, 'Elfe argenté', NULL, NULL, 'races/elfe-argente', NULL, NULL, 'Toutes les attaques magiques sont imparables.', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A73:Y75', NULL);
INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/elfe-dore', 'classeur_modes', 'race', 5, 'Elfe doré', NULL, NULL, 'races/elfe-dore', NULL, NULL, 'Les sorts infligent un stade au-dessus de leur altération d''état.', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A76:Y78', NULL);
INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/elfe-forestier', 'classeur_modes', 'race', 2, 'Elfe forestier', NULL, NULL, 'races/elfe-forestier', NULL, NULL, 'Chaque test d''Agilité se fait à 95% et impossible d''imposer de malus dessus.', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A67:Y69', NULL);
INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/elfe-noir', 'classeur_modes', 'race', 3, 'Elfe noir', NULL, NULL, 'races/elfe-noir', NULL, NULL, 'Permet de synthétiser un poison unique sur l''arme principale, inflige "poison 1" pendant tout le monde hyper. L''ennemi doit faire un jet de vigueur tous les débuts de tour pour ne pas encaisser les dégâts.', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A70:Y72', NULL);
INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/farfadet', 'classeur_modes', 'race', 6, 'Farfadet', NULL, NULL, 'races/farfadet', NULL, NULL, 'Permet d''avoir accès à tous les sorts de votre/vos magies, qui correspond à votre niveau puissance magique et inférieur.', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A79:Y81', NULL);
INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/felfe', 'classeur_modes', 'race', 7, 'Felfe', NULL, NULL, 'races/felfe', NULL, NULL, 'Peut voler, les dégâts et soins magiques sont augmentés de 2d, ceux qui doivent faire des jets pour esquiver les effets secondaires des sorts ont leur score divisé par 2.', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A82:Y84', NULL);
INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/fenrir', 'classeur_modes', 'race', 15, 'Fenrir', NULL, NULL, 'races/fenrir', NULL, NULL, 'Chaque test de Perception se fait à 95% et impossible d''imposer de malus dessus, impossible de prendre d''attaques surprises, cachées ou sournoises.', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A106:Y108', NULL);
INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/goleois', 'classeur_modes', 'race', 27, 'Goleois', NULL, NULL, 'races/goleois', NULL, NULL, 'Augmente les dégâts de tous les alliés de 5, le temps du mode hyper.', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A142:Y144', NULL);
INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/hujin', 'classeur_modes', 'race', 10, 'Hujin', NULL, NULL, 'races/hujin', NULL, NULL, 'Diminue d''un cran les dés des attaques physiques ou magiques subies', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A91:Y93', NULL);
