INSERT INTO mode_hyper_effet (id, version, portee, rang, libelle, magie_id, magie2_id, race_id, variante, variante_brut, effet, commentaire, origine, source_ref, remarque) VALUES ('classeur_modes:races/nain', 'classeur_modes', 'race', 8, 'Nain', NULL, NULL, 'races/nain', NULL, NULL, '2d de dégâts physiques en plus. Le sort malédiction ne marche.', NULL, 'annexes', 'Mode hyper et co › Mode Hyper › A85:Y87', NULL);
